style.css:
@-moz-document domain("teams.microsoft.com") {
/* General background and text */
    body, .ts-left-rail, .ts-app-bar, .ts-top-nav, .ts-main-area {
        background-color: #2f3136 !important;
        color: #dcddde !important;
        font-family: "Segoe UI", "Whitney", "Helvetica Neue", Arial, sans-serif !important;
    }

    /* Sidebar (Discord dark gray) */
    .ts-left-rail, .ts-app-bar {
        background-color: #202225 !important;
    }

    /* Channel/Chat list */
    .ts-channel-list, .ts-sidebar-channel-list {
        background-color: #2f3136 !important;
        color: #fff !important;
    }

    /* Top bar */
    .ts-top-nav {
        background-color: #202225 !important;
        border-bottom: 1px solid #2f3136 !important;
    }

    /* Chat area */
    .ts-message-list, .ts-main-area {
        background-color: #36393f !important;
    }
    .message-body {
        color: #dcddde !important;
    }

    /* Input box */
    .ts-message-box {
        background-color: #40444b !important;
        border-radius: 8px !important;
        color: #dcddde !important;
    }

    /* Buttons (Discord purple) */
    button, .ts-button {
        background-color: #5865f2 !important;
        color: #fff !important;
        border-radius: 5px !important;
        border: none !important;
    }
    button:hover, .ts-button:hover {
        background-color: #4752c4 !important;
    }

    /* Call controls (centered & Discord-like round) */
    .calling-bar button, .ts-calling-controls button {
        background-color: #5865f2 !important;
        border-radius: 50% !important;
        width: 40px !important;
        height: 40px !important;
    }
    .calling-bar button:hover, .ts-calling-controls button:hover {
        background-color: #4752c4 !important;
    }

    /* Mentions / highlights */
    .mention, .highlight {
        background-color: #5865f2 !important;
        color: #fff !important;
        border-radius: 3px !important;
        padding: 2px 4px !important;
    }
}
